package com.hellodoc.dto;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.List;
public record DoctorProfileUpdateRequest(@NotBlank @Size(max=100) String firstName,@NotBlank @Size(max=100) String lastName,@Size(max=32) String phone,@NotBlank @Size(max=300) String address,@NotBlank @Size(max=160) String serviceTitle,@NotBlank @Size(max=120) String specialty,@Min(5) @Max(240) int durationMinutes,@NotBlank String workStart,@NotBlank String workEnd,@NotEmpty List<@Pattern(regexp="[0-7]") String> workingDays,@Min(0) @Max(240) int pauseMinutes,@NotBlank @Size(max=300) String location,@Size(max=2000) String description,@NotEmpty List<@Valid ServiceInput> services,@NotBlank String currentPassword) { public record ServiceInput(@NotBlank @Size(max=160) String name,@NotBlank @Size(max=40) String price){} }
